from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const pill=','const notice=','const heading=','const categoryDefs=','function capabilities(','function press(')))
script=defs+'''
let requests=0,attached=true,key='access',reduced=false;function rebuild(){const f=document.getElementById('fixtures');f.innerHTML=capabilities();f.querySelectorAll('.page-heading,.notice,.section').forEach(x=>x.remove());f.querySelectorAll('tbody tr').forEach((x,i)=>{if(categoryDefs[i].key!==key)x.remove()});f.querySelectorAll('tbody td').forEach((c,i)=>c.id='CapabilityRow-cell-'+i);const b=f.querySelector('[data-action=permissions]');if(b)b.id='CapabilityRow-permissions';f.style.display=attached?'block':'none';document.body.classList.toggle('reduced',reduced)}rebuild();
function snapshot(){const b=document.querySelector('[data-action=permissions]'),row=document.querySelector('tbody tr');return{requests,english:lang==='en',key,focused:document.activeElement===b,attached,background:getComputedStyle(row).backgroundColor,opacity:getComputedStyle(row).opacity,button:b?.textContent??(lang==='ko'?'필요한 권한 보기':'Required permissions'),visible:!!b}}
async function record(){const res=await fetch('/evidence/preflight-capabilityrow-'+(new URLSearchParams(location.search).get('os')==='mac'?'mac':'windows')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot())});if(!res.ok)throw Error('Record failed');document.getElementById('capabilityrow-input-record').textContent='Input recorded'}
document.getElementById('capabilityrow-input-record').addEventListener('mousedown',e=>e.preventDefault());
let inputRecordTimer;function recordInputSoon(){clearTimeout(inputRecordTimer);inputRecordTimer=setTimeout(record,220)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b){recordInputSoon();return;}if(b.dataset.action==='permissions'){if(!reduced)press(b);requests++}if(b.id==='CapabilityRow-language'){lang=lang==='ko'?'en':'ko';rebuild()}if(b.id==='CapabilityRow-mount'){attached=!attached;rebuild()}if(b.id==='CapabilityRow-reduced'){reduced=!reduced;rebuild()}if(b.id==='CapabilityRow-data'){key=key==='access'?'data':'access';rebuild()}if(b.id==='capabilityrow-input-record')record();else recordInputSoon()});
'''
(o/'capabilityrow-input.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityRow Input · original isolation</title><link rel="stylesheet" href="capabilityrow-original.css"><style>.reduced *{transition:none!important;animation:none!important}.fixture{position:absolute;left:30px;top:60px;width:906px}</style><div id="fixtures" class="fixture"></div><button id="CapabilityRow-language">language</button><button id="CapabilityRow-reduced">reduced</button><button id="CapabilityRow-mount">mount</button><button id="CapabilityRow-data">data</button><button id="capabilityrow-input-record">Record CapabilityRow Input</button><script>'+script+'</script>');print('Source row input fixture prepared')
